def vectorized_reset(code):
    """Replaces explicit for loops with vectorized resets."""
    for i in range(len(code)):
        if isinstance(code[i], b2.NeuronGroup) or isinstance(code[i], b2.Population):
            code[i].reset = b2.vectorized_reset(code[i].reset)
    return code

