import brian2 as b2

def make_on_pre_post(self, target):
    # This method is used to create the "on_pre" and "on_post" statements for a Synapses object. 
    # The implementation is based on the Brian2 documentation (https://brian2.readthedocs.io/en/stable/reference/sections/synapses.html).
    # The on_pre statement sets the source object's state variables that are connected to the target object.
    # The on_post statement sets the target object's state variables that are connected to the source object.
    if target =='source':
        return f'Pre{self}'
    elif target == 'target':
        return f'Post{self}'
    else:
        raise ValueError(f"Target '{target}' not recognized for Synapses")

def rewrite_nested_loops(self):
        """
        Rewrite inefficient nested loops in synapses to vectorized operations.
        """
        for target in self._synapses:
            if not isinstance(target, Synapses):
                continue

            # Loop over all synapses in this group
            for pre, post in zip(target._pre, target._post):
                if self._update_rule =='stdp':
                    if not hasattr(pre,'stdp_update'):
                        pre.stdp_update = lambda pre, post: 0.0
                    if not hasattr(post,'stdp_update'):
                        post.stdp_update = lambda post, pre: 0.0

                # Convert to vectorized operations
                if self._update_rule =='stdp':
                    pre.stdp_update(pre, post)
                    post.stdp_update(post, pre)
                else:
                    target._synapses[target._synapses.index((pre, post))] = self._update_rule

