class TimeStepReplace:
    def __init__(self, model):
        self.model = model
        self.layers = list(self.model.children())
        self.seq = Sequential()

    def replace_time_step(self):
        for idx, layer in enumerate(self.layers):
            if isinstance(layer, nn.TimeDistributed):
                if hasattr(layer, 'to') and hasattr(layer.to,'seq'):
                    self.seq = self.seq.to(layer.to.seq)
                self.seq.add(layer)
            else:
                self.seq.add(layer)

        return self.seq

